static inline uint32_t ror32(uint32_t x, unsigned n)
{
    return (x >> n) | (x << (32 - n));
}

static inline uint32_t load_be32(const unsigned char *p)
{
    uint32_t v;
    memcpy(&v, p, 4);                 /* one lw + rev8 instead of 4 lbu */
    return __builtin_bswap32(v);
}

#define S0(x) (ror32(x, 7) ^ ror32(x, 18) ^ ((x) >> 3))
#define S1(x) (ror32(x, 17) ^ ror32(x, 19) ^ ((x) >> 10))
#define S2(x) (ror32(x, 2) ^ ror32(x, 13) ^ ror32(x, 22))
#define S3(x) (ror32(x, 6) ^ ror32(x, 11) ^ ror32(x, 25))

/* Ch = (e & f) + (g & ~e) (disjoint bits -> andn, two independent terms);
 * Maj = (a & b) + (c & (a ^ b)). */
#define RND(a, b, c, d, e, f, g, h, w, k)                              \
    do {                                                               \
        uint32_t t1_ = (h) + (k) + (w) + ((g) & ~(e)) + ((e) & (f)) + S3(e); \
        (d) += t1_;                                                    \
        (h) = t1_ + S2(a) + ((a) & (b)) + ((c) & ((a) ^ (b)));         \
    } while (0)

#define MSG(i) (W[(i) & 15] += S1(W[((i) - 2) & 15]) + W[((i) - 7) & 15] + \
                               S0(W[((i) - 15) & 15]))

#define RND8(i, WX)                                                    \
    RND(a, b, c, d, e, f, g, h, WX((i) + 0), K[(i) + 0]);              \
    RND(h, a, b, c, d, e, f, g, WX((i) + 1), K[(i) + 1]);              \
    RND(g, h, a, b, c, d, e, f, WX((i) + 2), K[(i) + 2]);              \
    RND(f, g, h, a, b, c, d, e, WX((i) + 3), K[(i) + 3]);              \
    RND(e, f, g, h, a, b, c, d, WX((i) + 4), K[(i) + 4]);              \
    RND(d, e, f, g, h, a, b, c, WX((i) + 5), K[(i) + 5]);              \
    RND(c, d, e, f, g, h, a, b, WX((i) + 6), K[(i) + 6]);              \
    RND(b, c, d, e, f, g, h, a, WX((i) + 7), K[(i) + 7])

#define WIN(i) W[(i)]

/* State is kept in locals across all blocks; the 16-word message schedule
 * is a rolling window (fully unrolled, constant indices -> registers). */
static size_t sha256_blocks(mbedtls_sha256_context *ctx,
                            const unsigned char *data, size_t len)
{
    uint32_t a = ctx->state[0], b = ctx->state[1], c = ctx->state[2], d = ctx->state[3];
    uint32_t e = ctx->state[4], f = ctx->state[5], g = ctx->state[6], h = ctx->state[7];
    size_t processed = 0;

    while (len >= SHA256_BLOCK_SIZE) {
        uint32_t W[16];
        uint32_t A0 = a, B0 = b, C0 = c, D0 = d, E0 = e, F0_ = f, G0 = g, H0 = h;
        int i;

        for (i = 0; i < 16; i++) {
            W[i] = load_be32(data + 4 * i);
        }

        RND8(0, WIN);
        RND8(8, WIN);
        RND8(16, MSG);
        RND8(24, MSG);
        RND8(32, MSG);
        RND8(40, MSG);
        RND8(48, MSG);
        RND8(56, MSG);

        a += A0; b += B0; c += C0; d += D0;
        e += E0; f += F0_; g += G0; h += H0;

        data += SHA256_BLOCK_SIZE;
        len -= SHA256_BLOCK_SIZE;
        processed += SHA256_BLOCK_SIZE;
    }

    ctx->state[0] = a; ctx->state[1] = b; ctx->state[2] = c; ctx->state[3] = d;
    ctx->state[4] = e; ctx->state[5] = f; ctx->state[6] = g; ctx->state[7] = h;
    return processed;
}

int mbedtls_internal_sha256_process(mbedtls_sha256_context *ctx,
                                    const unsigned char data[SHA256_BLOCK_SIZE])
{
    sha256_blocks(ctx, data, SHA256_BLOCK_SIZE);
    return 0;
}

static size_t mbedtls_internal_sha256_process_many(
    mbedtls_sha256_context *ctx, const uint8_t *data, size_t len)
{
    return sha256_blocks(ctx, data, len);
}

int mbedtls_sha256_update(mbedtls_sha256_context *ctx,
                          const unsigned char *input,
                          size_t ilen)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    size_t fill;
    uint32_t left;

    if (ilen == 0) {
        return 0;
    }

    left = ctx->total[0] & 0x3F;
    fill = SHA256_BLOCK_SIZE - left;

    ctx->total[0] += (uint32_t) ilen;
    ctx->total[0] &= 0xFFFFFFFF;

    if (ctx->total[0] < (uint32_t) ilen) {
        ctx->total[1]++;
    }

    if (left && ilen >= fill) {
        memcpy((void *) (ctx->buffer + left), input, fill);

        if ((ret = mbedtls_internal_sha256_process(ctx, ctx->buffer)) != 0) {
            return ret;
        }

        input += fill;
        ilen  -= fill;
        left = 0;
    }

    while (ilen >= SHA256_BLOCK_SIZE) {
        size_t processed =
            mbedtls_internal_sha256_process_many(ctx, input, ilen);
        if (processed < SHA256_BLOCK_SIZE) {
            return MBEDTLS_ERR_ERROR_GENERIC_ERROR;
        }

        input += processed;
        ilen  -= processed;
    }

    if (ilen > 0) {
        memcpy((void *) (ctx->buffer + left), input, ilen);
    }

    return 0;
}

int mbedtls_sha256_finish(mbedtls_sha256_context *ctx,
                          unsigned char *output)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    uint32_t used;
    uint32_t high, low;
    int truncated = 0;

    used = ctx->total[0] & 0x3F;

    ctx->buffer[used++] = 0x80;

    if (used <= 56) {

        memset(ctx->buffer + used, 0, 56 - used);
    } else {

        memset(ctx->buffer + used, 0, SHA256_BLOCK_SIZE - used);

        if ((ret = mbedtls_internal_sha256_process(ctx, ctx->buffer)) != 0) {
            goto exit;
        }

        memset(ctx->buffer, 0, 56);
    }

    high = (ctx->total[0] >> 29)
           | (ctx->total[1] <<  3);
    low  = (ctx->total[0] <<  3);

    MBEDTLS_PUT_UINT32_BE(high, ctx->buffer, 56);
    MBEDTLS_PUT_UINT32_BE(low,  ctx->buffer, 60);

    if ((ret = mbedtls_internal_sha256_process(ctx, ctx->buffer)) != 0) {
        goto exit;
    }

    MBEDTLS_PUT_UINT32_BE(ctx->state[0], output,  0);
    MBEDTLS_PUT_UINT32_BE(ctx->state[1], output,  4);
    MBEDTLS_PUT_UINT32_BE(ctx->state[2], output,  8);
    MBEDTLS_PUT_UINT32_BE(ctx->state[3], output, 12);
    MBEDTLS_PUT_UINT32_BE(ctx->state[4], output, 16);
    MBEDTLS_PUT_UINT32_BE(ctx->state[5], output, 20);
    MBEDTLS_PUT_UINT32_BE(ctx->state[6], output, 24);

    if (!truncated) {
        MBEDTLS_PUT_UINT32_BE(ctx->state[7], output, 28);
    }

    ret = 0;

exit:
    mbedtls_sha256_free(ctx);
    return ret;
}

int mbedtls_sha256(const unsigned char *input,
                   size_t ilen,
                   unsigned char *output,
                   int is224)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    mbedtls_sha256_context ctx;

    if (is224 != 0) {
        return MBEDTLS_ERR_SHA256_BAD_INPUT_DATA;
    }

    mbedtls_sha256_init(&ctx);

    if ((ret = mbedtls_sha256_starts(&ctx, is224)) != 0) {
        goto exit;
    }

    if ((ret = mbedtls_sha256_update(&ctx, input, ilen)) != 0) {
        goto exit;
    }

    if ((ret = mbedtls_sha256_finish(&ctx, output)) != 0) {
        goto exit;
    }

exit:
    mbedtls_sha256_free(&ctx);

    return ret;
}

