static inline uint64_t ror64(uint64_t x, unsigned n)
{
    return (x >> n) | (x << (64 - n));
}

static inline uint64_t load_be64(const unsigned char *p)
{
    uint64_t v;
    memcpy(&v, p, 8);                 /* one ld + rev8 */
    return __builtin_bswap64(v);
}

#define S0(x) (ror64(x, 1) ^ ror64(x, 8) ^ ((x) >> 7))
#define S1(x) (ror64(x, 19) ^ ror64(x, 61) ^ ((x) >> 6))
#define S2(x) (ror64(x, 28) ^ ror64(x, 34) ^ ror64(x, 39))
#define S3(x) (ror64(x, 14) ^ ror64(x, 18) ^ ror64(x, 41))

/* Ch = (e & f) + (g & ~e) (andn), Maj = (a & b) + (c & (a ^ b)). */
#define RND(a, b, c, d, e, f, g, h, w, k)                              \
    do {                                                               \
        uint64_t t1_ = (h) + (k) + (w) + ((g) & ~(e)) + ((e) & (f)) + S3(e); \
        (d) += t1_;                                                    \
        (h) = t1_ + S2(a) + ((a) & (b)) + ((c) & ((a) ^ (b)));         \
    } while (0)

#define MSG(i) (W[(i) & 15] += S1(W[((i) - 2) & 15]) + W[((i) - 7) & 15] + \
                               S0(W[((i) - 15) & 15]))
#define WIN(i) W[(i)]

#define RND8(i, WX)                                                    \
    RND(a, b, c, d, e, f, g, h, WX((i) + 0), K[(i) + 0]);              \
    RND(h, a, b, c, d, e, f, g, WX((i) + 1), K[(i) + 1]);              \
    RND(g, h, a, b, c, d, e, f, WX((i) + 2), K[(i) + 2]);              \
    RND(f, g, h, a, b, c, d, e, WX((i) + 3), K[(i) + 3]);              \
    RND(e, f, g, h, a, b, c, d, WX((i) + 4), K[(i) + 4]);              \
    RND(d, e, f, g, h, a, b, c, WX((i) + 5), K[(i) + 5]);              \
    RND(c, d, e, f, g, h, a, b, WX((i) + 6), K[(i) + 6]);              \
    RND(b, c, d, e, f, g, h, a, WX((i) + 7), K[(i) + 7])

/* State in locals across blocks; rolling 16-word schedule, unrolled rounds. */
static size_t sha512_blocks(mbedtls_sha512_context *ctx,
                            const unsigned char *data, size_t len)
{
    uint64_t a = ctx->state[0], b = ctx->state[1], c = ctx->state[2], d = ctx->state[3];
    uint64_t e = ctx->state[4], f = ctx->state[5], g = ctx->state[6], h = ctx->state[7];
    size_t processed = 0;

    while (len >= SHA512_BLOCK_SIZE) {
        uint64_t W[16];
        uint64_t A0 = a, B0 = b, C0 = c, D0 = d, E0 = e, F0_ = f, G0 = g, H0 = h;
        int i;

        for (i = 0; i < 16; i++) {
            W[i] = load_be64(data + 8 * i);
        }

        RND8(0, WIN);
        RND8(8, WIN);
        RND8(16, MSG);
        RND8(24, MSG);
        RND8(32, MSG);
        RND8(40, MSG);
        RND8(48, MSG);
        RND8(56, MSG);
        RND8(64, MSG);
        RND8(72, MSG);

        a += A0; b += B0; c += C0; d += D0;
        e += E0; f += F0_; g += G0; h += H0;

        data += SHA512_BLOCK_SIZE;
        len -= SHA512_BLOCK_SIZE;
        processed += SHA512_BLOCK_SIZE;
    }

    ctx->state[0] = a; ctx->state[1] = b; ctx->state[2] = c; ctx->state[3] = d;
    ctx->state[4] = e; ctx->state[5] = f; ctx->state[6] = g; ctx->state[7] = h;
    return processed;
}

int mbedtls_internal_sha512_process(mbedtls_sha512_context *ctx,
                                    const unsigned char data[SHA512_BLOCK_SIZE])
{
    sha512_blocks(ctx, data, SHA512_BLOCK_SIZE);
    return 0;
}

static size_t mbedtls_internal_sha512_process_many(
    mbedtls_sha512_context *ctx, const uint8_t *data, size_t len)
{
    return sha512_blocks(ctx, data, len);
}

int mbedtls_sha512_update(mbedtls_sha512_context *ctx,
                          const unsigned char *input,
                          size_t ilen)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    size_t fill;
    unsigned int left;

    if (ilen == 0) {
        return 0;
    }

    left = (unsigned int) (ctx->total[0] & 0x7F);
    fill = SHA512_BLOCK_SIZE - left;

    ctx->total[0] += (uint64_t) ilen;

    if (ctx->total[0] < (uint64_t) ilen) {
        ctx->total[1]++;
    }

    if (left && ilen >= fill) {
        memcpy((void *) (ctx->buffer + left), input, fill);

        if ((ret = mbedtls_internal_sha512_process(ctx, ctx->buffer)) != 0) {
            return ret;
        }

        input += fill;
        ilen  -= fill;
        left = 0;
    }

    while (ilen >= SHA512_BLOCK_SIZE) {
        size_t processed =
            mbedtls_internal_sha512_process_many(ctx, input, ilen);
        if (processed < SHA512_BLOCK_SIZE) {
            return MBEDTLS_ERR_ERROR_GENERIC_ERROR;
        }

        input += processed;
        ilen  -= processed;
    }

    if (ilen > 0) {
        memcpy((void *) (ctx->buffer + left), input, ilen);
    }

    return 0;
}

int mbedtls_sha512_finish(mbedtls_sha512_context *ctx,
                          unsigned char *output)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    unsigned used;
    uint64_t high, low;
    int truncated = 0;

    used = ctx->total[0] & 0x7F;

    ctx->buffer[used++] = 0x80;

    if (used <= 112) {

        memset(ctx->buffer + used, 0, 112 - used);
    } else {

        memset(ctx->buffer + used, 0, SHA512_BLOCK_SIZE - used);

        if ((ret = mbedtls_internal_sha512_process(ctx, ctx->buffer)) != 0) {
            goto exit;
        }

        memset(ctx->buffer, 0, 112);
    }

    high = (ctx->total[0] >> 61)
           | (ctx->total[1] <<  3);
    low  = (ctx->total[0] <<  3);

    sha512_put_uint64_be(high, ctx->buffer, 112);
    sha512_put_uint64_be(low,  ctx->buffer, 120);

    if ((ret = mbedtls_internal_sha512_process(ctx, ctx->buffer)) != 0) {
        goto exit;
    }

    sha512_put_uint64_be(ctx->state[0], output,  0);
    sha512_put_uint64_be(ctx->state[1], output,  8);
    sha512_put_uint64_be(ctx->state[2], output, 16);
    sha512_put_uint64_be(ctx->state[3], output, 24);
    sha512_put_uint64_be(ctx->state[4], output, 32);
    sha512_put_uint64_be(ctx->state[5], output, 40);

    truncated = ctx->is384;

    if (!truncated) {
        sha512_put_uint64_be(ctx->state[6], output, 48);
        sha512_put_uint64_be(ctx->state[7], output, 56);
    }

    ret = 0;

exit:
    mbedtls_sha512_free(ctx);
    return ret;
}

int mbedtls_sha512(const unsigned char *input,
                   size_t ilen,
                   unsigned char *output,
                   int is384)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    mbedtls_sha512_context ctx;

    if (is384 != 0 && is384 != 1) {
        return MBEDTLS_ERR_SHA512_BAD_INPUT_DATA;
    }

    mbedtls_sha512_init(&ctx);

    if ((ret = mbedtls_sha512_starts(&ctx, is384)) != 0) {
        goto exit;
    }

    if ((ret = mbedtls_sha512_update(&ctx, input, ilen)) != 0) {
        goto exit;
    }

    if ((ret = mbedtls_sha512_finish(&ctx, output)) != 0) {
        goto exit;
    }

exit:
    mbedtls_sha512_free(&ctx);

    return ret;
}
